const item = $input.item.json;
const url = item['web'] || item['Tiene web?'] || '';
let domain = '';
try {
  if (url.startsWith('http')) {
    domain = new URL(url).hostname.replace(/^www\./, '');
  } else if (url.includes('.')) {
    domain = url.replace(/^www\./, '').split('/')[0];
  } else {
    domain = (item['Nombre Hotel'] || '').toLowerCase().replace(/\s+/g, '') + '.com';
  }
} catch(e) {
  domain = url.replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0];
}
return { json: { ...item, _domain: domain } };

const hunterData = $input.item.json;
const emails = hunterData?.data?.emails || [];
const firstEmail = emails.length > 0 ? emails[0].value : null;
return { json: { ...$input.item.json, _hunterEmail: firstEmail || '', _hasEmail: firstEmail !== null && firstEmail !== '' } };

let bajas = new Set();
try {
  for (const r of $('Get Bajas').all()) {
    const e = String((r.json && (r.json.Email ?? r.json.email)) || '').toLowerCase().trim();
    if (e) bajas.add(e);
  }
} catch (err) { /* fail-open: si no se puede leer la lista, no filtra */ }
return $input.all().filter(it => {
  const email = String((it.json._hunterEmail ?? it.json.to_email) || '').toLowerCase().trim();
  return !email || !bajas.has(email);
});

let aiResponse;
try {
  const content = $input.item.json.choices[0].message.content;
  const cleaned = content.replace(/^```json\n?|\n?```$/g, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  aiResponse = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned);
} catch(e) {
  aiResponse = { subject: 'Emma para tu hotel - respuesta 24/7', apertura: 'Vi tu hotel y creo que Emma puede ayudarte a no perder mas consultas.' };
}

const _src = $('Filtrar bajas').item.json;
const hotelName = _src['Nombre Hotel'] || '';
const hunterEmail = _src._hunterEmail || '';
const hotelEncoded = encodeURIComponent(hotelName);
const demoUrl = 'https://timelessai.pro/?hotel=' + hotelEncoded;
const apertura = (aiResponse.apertura && String(aiResponse.apertura).trim()) ? String(aiResponse.apertura).trim() : ('Te escribo porque trabajo con hoteles boutique y creo que Emma te puede ahorrar consultas perdidas.');

return {
  json: {
    subject: aiResponse.subject,
    body: '<p>Hola,</p><p>' + apertura + '</p><p>La mayoría de los hoteles boutique pierden reservas entre las 10pm y las 8am, cuando no hay nadie respondiendo mensajes.</p><p>En Sun Life Beach Hotel (Florida) resolvimos eso con Emma — una recepcionista virtual que responde en menos de 3 segundos, a cualquier hora, en el idioma del huésped. La primera semana atendió 40+ consultas. La mayoría, de madrugada.</p><p>Armamos una demo con el nombre de tu hotel para que lo veas en contexto real:<br><a href="' + demoUrl + '">Ver demo personalizada →</a></p><p>Saludos,<br>Matías<br>Timeless AI</p><p style="font-size:12px;color:#999;margin-top:24px;">Timeless AI · Zúrich, Suiza · team@timelessai.pro<br>Te escribo porque encontré el contacto de tu hotel públicamente. Para no recibir más emails, <a href="https://timelessai.pro/baja.html?e=' + encodeURIComponent(hunterEmail) + '">hacé clic acá para darte de baja</a> o respondé BAJA.</p>',
    to_email: hunterEmail,
    'Nombre Hotel': hotelName,
    _hunterEmail: hunterEmail
  }
};
